        ulTokens = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            ulTokens[i] = coins[i];
        }
        virtualPrice = ICurveRegistry(registry)
            .get_virtual_price_from_lp_token(crvLp);
        return (pool, ulTokens, virtualPrice);
    }

